import sys

def main():
    m, n = map(int, sys.stdin.read().split())
    f = [0, 1]
    while len(f) < m * n:
        f.append(f[-1] + f[-2])
    g = [[0] * n for _ in range(m)]
    top, bot, left, right = 0, m - 1, 0, n - 1
    k = 0
    while top <= bot and left <= right:
        for c in range(left, right + 1):
            g[top][c] = f[k]
            k += 1
        top += 1
        for r in range(top, bot + 1):
            g[r][right] = f[k]
            k += 1
        right -= 1
        if top <= bot:
            for c in range(right, left - 1, -1):
                g[bot][c] = f[k]
                k += 1
            bot -= 1
        if left <= right:
            for r in range(bot, top - 1, -1):
                g[r][left] = f[k]
                k += 1
            left += 1
    print('\n'.join(' '.join(map(str, row)) for row in g))

